42|function rays(n: number, r1: number, r2: number, jit = 0): string {
43|  return Array.from({ length: n }, (_, i) => {
44|    const a = (i / n) * Math.PI * 2 + 0.07;
45|    const j = jit ? (((i * 37) % 7) - 3) * jit : 0;
46|    const b = r1 + (i % 2 ? 0 : -2);
47|    const e = r2 + (i % 2 ? -3 : 0) + j;
48|    return `M${(50 + b * Math.cos(a)).toFixed(1)} ${(50 + b * Math.sin(a)).toFixed(1)}L${(50 + e * Math.cos(a)).toFixed(1)} ${(50 + e * Math.sin(a)).toFixed(1)}`;
49|  }).join("");
50|}
