56|      {DROPS[props.s]!.map(([x, y], i) => (
57|        <path
58|          key={i}
59|          className="drop"
60|          style={{ "--i": i, stroke: props.stroke } as CSSProperties}
61|          d={`M${x} ${y}l-2.2 ${len}`}
62|          fill="none"
63|          strokeWidth={props.width}
64|          strokeLinecap={props.linecap}
65|        />
66|      ))}
67|    </>
68|  );
