1|"use client";
2|
3|import { useEffect, useRef, useState } from "react";
4|import {
5|  AMBIENCES,
6|  DEFAULT_AMBIENCE_VOLUME,
7|  ambienceLabel,
8|  levelById,
9|  nextLevel,
10|} from "@/core/ambience";
11|import { loadAmbiencePrefs, saveAmbiencePrefs } from "./ambience-prefs";
12|import { AmbienceController } from "./ambience-controller";
13|import { WebAmbienceEngine } from "./ambience-engine";
14|import { Icon } from "./icons";
15|import { hasRainArt, type RainIconName } from "./icons-rain";
16|import { DEFAULT_SKIN } from "./skin";
17|import { useSkin } from "./use-skin";
18|
19|const RAIN = AMBIENCES[0]!;
20|
21|// One drop cycle: how long the button replays its animation after a click.
22|const ANIM_MS = 1400;
23|
24|// The button owns its controller: it loads prefs once, saves on change,
25|// and starts the stored level on the first gesture anywhere in the page.
26|export function RainAmbience({ muted }: { muted: boolean }) {
27|  const controllerRef = useRef<AmbienceController | null>(null);
28|  const [level, setLevel] = useState("off");
29|  const [volume, setVolume] = useState(DEFAULT_AMBIENCE_VOLUME);
30|  const [burst, setBurst] = useState(0);
31|  // Server render uses the default so hydration matches; the live skin
32|  // applies on mount via useSyncExternalStore.
33|  const skin = useSkin();
34|  // Rain art exists only for three skins; the rest render the default.
35|  const artSkin = hasRainArt(skin) ? skin : DEFAULT_SKIN;
36|  const burstTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
37|
38|  useEffect(() => {
39|    const controller = new AmbienceController(new WebAmbienceEngine());
40|    controllerRef.current = controller;
41|    const prefs = loadAmbiencePrefs();
42|    if (prefs) {
43|      controller.setVolume(prefs.volume);
44|      setVolume(prefs.volume);
45|      if (prefs.level !== "off" && levelById(RAIN, prefs.level)) {
46|        controller.setLevel(prefs.level);
47|        setLevel(prefs.level);
48|      }
49|    }
50|    const unlock = () => void controller.unlock();
51|    document.addEventListener("pointerdown", unlock, { once: true });
52|    document.addEventListener("keydown", unlock, { once: true });
53|    return () => {
54|      document.removeEventListener("pointerdown", unlock);
55|      document.removeEventListener("keydown", unlock);
56|      controller.dispose();
57|      controllerRef.current = null;
58|    };
59|  }, []);
60|
61|  useEffect(() => {
62|    controllerRef.current?.setMuted(muted);
63|  }, [muted]);
64|
65|  useEffect(
66|    () => () => {
67|      if (burstTimer.current) clearTimeout(burstTimer.current);
68|    },
69|    [],
70|  );
71|
72|  function cycle() {
73|    const controller = controllerRef.current;
74|    if (!controller) return;
75|    void controller.unlock();
76|    const id = nextLevel(RAIN, level);
77|    controller.setLevel(id);
78|    setLevel(id);
79|    saveAmbiencePrefs({ level: id, volume });
80|    setBurst((b) => b + 1);
81|    if (burstTimer.current) clearTimeout(burstTimer.current);
82|    burstTimer.current = setTimeout(() => setBurst(0), ANIM_MS);
83|  }
84|
85|  function changeVolume(value: number) {
86|    controllerRef.current?.setVolume(value);
87|    setVolume(value);
88|    saveAmbiencePrefs({ level, volume: value });
89|  }
90|
91|  const label = ambienceLabel(RAIN, level);
92|  return (
93|    <>
94|      <button
95|        type="button"
96|        className="skip rain"
97|        data-level={level}
98|        data-art={artSkin}
99|        data-anim={burst ? "1" : undefined}
100|        onClick={cycle}
101|        aria-label={label}
102|        title={label}
103|      >
104|        {/* key replays the one-shot animation on rapid clicks */}
105|        <span className="face" key={burst}>
106|          <Icon name={`rain-${level}` as RainIconName} skin={artSkin} />
107|        </span>
108|      </button>
109|      {level !== "off" ? (
110|        <input
111|          type="range"
112|          className="rain-volume"
113|          min={0}
114|          max={1}
115|          step={0.05}
116|          value={volume}
117|          onChange={(e) => changeVolume(Number(e.target.value))}
118|          aria-label="Rain volume"
119|        />
120|      ) : null}
121|    </>
122|  );
123|}

