1|import { readFileSync } from "node:fs";
2|import { describe, expect, it } from "vitest";
3|
4|// No DOM test setup in this repo, so this pins the still-and-frameless
5|// contract against the sources directly.
6|const button = readFileSync(new URL("./rain-button.tsx", import.meta.url), "utf8");
7|const css = readFileSync(new URL("./styles/ambience.css", import.meta.url), "utf8");
8|
9|describe("rain button still and frameless", () => {
10|  it("has no idle animation loop", () => {
11|    expect(css).not.toMatch(/infinite/);
12|  });
13|
14|  it("plays hover animations only under hover media", () => {
15|    expect(css).toMatch(/@media \(hover: hover\)/);
16|    const withoutHoverBlock = css.replace(/@media \(hover: hover\) \{[\s\S]*?\n\}\n/, "");
17|    expect(withoutHoverBlock).not.toMatch(/\.skip\.rain:hover/);
18|  });
19|
20|  it("keys state-change animations on data-anim, never on mount", () => {
21|    for (const cls of ["face", "drop", "bolt", "etch", "draw", "bloom", "wet"]) {
22|      expect(css).toMatch(new RegExp(`\\[data-anim\\][\\s\\S]*?\\.${cls}[\\s,{]`));
23|    }
24|    expect(css).not.toMatch(/\.skip\.rain \.face\s*\{[^}]*animation:/);
25|  });
26|
27|  it("keeps the button boxless with the art sized inside the hit area", () => {
28|    expect(css).toMatch(/\.skip\.rain \{[^}]*border: none/);
29|    expect(css).toMatch(/\.skip\.rain \{[^}]*background: transparent/);
30|    expect(css).toMatch(/\.skip\.rain \{[^}]*box-shadow: none/);
31|    expect(css).toMatch(/\.skip\.rain svg \{[^}]*width: 30px/);
32|    expect(css).toMatch(/\.skip\.rain svg \{[^}]*overflow: visible/);
33|    expect(css).toMatch(/svg \[fill\]:not\(\[stroke\]\) \{\s*stroke: none;\s*\}/);
34|    expect(css).toMatch(
35|      /\.player \.skip\.rain:focus-visible \{\s*outline: 2px solid var\(--color-accent\);\s*outline-offset: 2px;\s*border-radius: 6px;\s*\}/,
36|    );
37|    expect(css).toMatch(/\.player \.skip\.rain:focus:not\(:focus-visible\) \{\s*outline: none;\s*\}/);
38|  });
39|
40|  it("disables rain animations under reduced motion, allowing only a short fade", () => {
41|    const reduced = css.slice(css.indexOf("prefers-reduced-motion"));
42|    expect(reduced).toMatch(/animation: none/);
43|    expect(reduced).toMatch(/transition: none/);
44|    expect(reduced).toMatch(/\[data-anim\] \.face/);
45|    expect(reduced).toMatch(/200ms/);
46|    expect(reduced).not.toMatch(/infinite/);
47|  });
48|
49|  it("renders the registry icon for the level with no inline svg", () => {
50|    expect(button).toMatch(/<Icon name=\{`rain-\$\{level\}`/);
51|    expect(button).toMatch(/<span className="face" key=\{burst\}>/);
52|    expect(button).not.toContain("<svg");
53|  });
54|
55|  it("reads the skin from the skin owner with the default for hydration", () => {
56|    expect(button).toMatch(/const skin = useSkin\(\);/);
57|    expect(button).toMatch(/hasRainArt\(skin\) \? skin : DEFAULT_SKIN/);
58|    expect(button).not.toMatch(/document\.documentElement\.dataset\.skin/);
59|  });
60|
61|  it("renders the resolved art skin and keys the rain CSS on it", () => {
62|    expect(button).toMatch(/data-art=\{artSkin\}/);
63|    expect(button).toMatch(/skin=\{artSkin\}/);
64|    expect(css).not.toMatch(/html\[data-skin/);
65|    for (const art of ["engraving", "watercolor", "ink"]) {
66|      expect(css).toMatch(new RegExp(`\\.skip\\.rain\\[data-art="${art}"\\]`));
67|    }
68|    expect(css).toMatch(/html\[data-theme="dark"\] \.player \.skip\.rain\[data-art=/);
69|  });
70|
71|  it("sets data-anim on click and clears it on a timeout with cleanup", () => {
72|    expect(button).toMatch(/data-anim=\{burst \? "1" : undefined\}/);
73|    expect(button).toMatch(/setTimeout\(\(\) => setBurst\(0\), ANIM_MS\)/);
74|    expect(button).toMatch(/clearTimeout\(burstTimer\.current\)/);
75|  });
76|});

